import { Component } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from 'src/app/service/auth.service';
import { login } from '../Models/login';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {

  constructor(private router:Router, private fb : FormBuilder, private service : AuthService){}

  loginForm = this.fb.group({
    email : ['', [Validators.required,Validators.email]],
    password : ['',[Validators.required, Validators.minLength(6)]]
  });

  loading = false;
  errorMessage = '';

  onSubmit() {
    if (this.loginForm.invalid) {
      this.loginForm.markAllAsTouched();
      return;
    }

    this.loading = true;
    this.errorMessage = '';

    this.service.login(this.loginForm.value as login).subscribe({
      next: (res) => {
        const result: any = res;

        localStorage.setItem("token", result.token);
        localStorage.setItem("role", result.role);
        localStorage.setItem("id", result.id);

        this.loading = false;
        this.loginForm.reset();

        if (result.role == 'COMPANY') {
          this.router.navigate(['/company/company-dashboard']);
        }

        if (result.role == 'JOBSEEKER') {
          this.router.navigate(["/seeker/jobseeker-dashboard"]);
        }
      },
      error: (err) => {
        this.loading = false;
        this.errorMessage = err.error?.message ?? 'Invalid email or password.';
      }
    });
  }

}
<div class="page">
<app-header variant="guest"></app-header>

<div class="auth-wrap">
  <div class="auth-card">
    <span class="mono-label" style="color:var(--amber-dk)">Welcome back</span>
    <h2>Log in to HireHub</h2>
    <form [formGroup]="loginForm" (ngSubmit)="onSubmit()">
      <div class="field"><label>Email</label><input formControlName="email" type="email" placeholder="you@email.com"></div>
      <div class="field"><label>Password</label><input formControlName="password" type="password" placeholder="&bull;&bull;&bull;&bull;&bull;&bull;&bull;&bull;"></div>
      <p *ngIf="errorMessage" style="color:#c0392b;font-size:13px;margin:4px 0 12px;">{{ errorMessage }}</p>
      <button type="submit" class="btn btn-primary btn-block" [disabled]="loading">{{ loading ? 'Logging in…' : 'Log in' }}</button>
    </form>
    <p class="muted" style="font-size:13px;margin-top:18px;text-align:center;">No account? <a routerLink="/auth/register" style="color:var(--indigo);font-weight:600;">Register as Job Seeker or Company</a>.</p>
  </div>
</div>

<app-footer></app-footer>
</div>
